const size_t otla_logo_bmp_size = 17462;

wxImage LoadOtla_logoBmp()
{
    wxMemoryInputStream memStream(otla_logo_bmp_data, otla_logo_bmp_size);
    wxImage img;
    if (img.LoadFile(memStream, wxBITMAP_TYPE_BMP))
        return img;
    return wxImage();
}

